package factory

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/surendratiwari3/paota/config"
	appErrors "github.com/surendratiwari3/paota/schema/errors"
)

// stubConfigProvider is a hand written stub so this test does not depend on
// mocks generated by mockery.
type stubConfigProvider struct {
	cfg *config.Config
}

func (s *stubConfigProvider) ReadFromEnv() error                       { return nil }
func (s *stubConfigProvider) SetApplicationConfig(config.Config) error { return nil }
func (s *stubConfigProvider) ValidateConfig(config.Config) error       { return nil }
func (s *stubConfigProvider) GetConfig() *config.Config                { return s.cfg }

func TestCreateBrokerUnsupported(t *testing.T) {
	tests := []struct {
		name       string
		brokerName string
	}{
		{"unknown broker", "kafka"},
		{"empty broker", ""},
		{"case sensitive", "AMQP"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			f := &Factory{}
			brk, err := f.CreateBroker(&stubConfigProvider{cfg: &config.Config{Broker: tt.brokerName}})

			assert.Nil(t, brk)
			assert.True(t, errors.Is(err, appErrors.ErrUnsupportedBroker), "got %v", err)
		})
	}
}

// TestCreateBrokerAmqpWithoutAmqpConfig covers the nil dereference that used to
// crash on start-up when the broker was set to amqp but no AMQP block was
// configured.
func TestCreateBrokerAmqpWithoutAmqpConfig(t *testing.T) {
	f := &Factory{}

	assert.NotPanics(t, func() {
		brk, err := f.CreateBroker(&stubConfigProvider{cfg: &config.Config{Broker: "amqp"}})
		assert.Nil(t, brk)
		assert.Error(t, err)
	})
}

func TestCreateStore(t *testing.T) {
	tests := []struct {
		name      string
		store     string
		expectErr error
	}{
		{"no store configured", "", nil},
		{"unsupported store", "mongodb", appErrors.ErrUnsupportedStore},
		{"unknown store", "redis", appErrors.ErrUnsupportedStore},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			f := &Factory{}
			err := f.CreateStore(&stubConfigProvider{cfg: &config.Config{Store: tt.store}})

			if tt.expectErr == nil {
				assert.NoError(t, err)
				return
			}
			assert.True(t, errors.Is(err, tt.expectErr), "got %v", err)
		})
	}
}

func TestCreateTaskRegistrar(t *testing.T) {
	f := &Factory{}
	provider := &stubConfigProvider{cfg: &config.Config{Broker: "amqp", TaskQueueName: "tasks"}}

	registrar := f.CreateTaskRegistrar(nil, provider)

	require.NotNil(t, registrar)
	assert.Equal(t, uint(0), registrar.GetRegisteredTaskCount())

	require.NoError(t, registrar.RegisterTasks(map[string]interface{}{
		"sendEmail": func() error { return nil },
	}))
	assert.True(t, registrar.IsTaskRegistered("sendEmail"))
}

func TestFactoryImplementsIFactory(t *testing.T) {
	var _ IFactory = &Factory{}
}
